effect.shader:
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec2 cell = floor(acScreenNorm*size);
    vec2 r = vec2(rand(cell), rand(cell+7.13)) - 0.5;
    vec2 uv = acScreenNorm + r*amount*0.12;
    gl_FragColor = texture2DCv(inputImg.texture, clamp(uv,0.0,1.0));
}
